package com.cbdog.ptvbox
import org.junit.Assert.*
import org.junit.Test
import org.json.JSONObject

class Version056Test {
 @Test fun trackLanguagesAndFormats(){assertEquals("日语 · 5.1声道 · AAC",TrackLabels056.label("jpn",null,"mp4a.40.2",null,6,1));assertTrue(TrackLabels056.label("zh-Hant",null,null,"application/x-subrip",-1,1).contains("中文（繁体） · SRT"));assertTrue(TrackLabels056.label("eng",null,"eac3",null,8,1).contains("英语 · 7.1声道 · Dolby Digital Plus"))}
 @Test fun coverageIsBounded(){for(percent in listOf(25,50,75,100)){val area=DanmakuLayout056.area(1080f,percent);val lanes=DanmakuLayout056.lanes(area,30f);assertTrue(30f+(lanes-1)*45f<=area)};assertEquals(540f,DanmakuLayout056.area(1080f,50))}
 @Test fun danmakuTravelsFullWidthByDefault(){assertEquals(2060f,DanmakuLayout056.travel(1920f,140f,100));assertEquals(-140f,DanmakuLayout056.xAt(1920f,140f,100,8f,8f));assertTrue(DanmakuLayout056.xAt(1920f,140f,100,8f,7.5f)<0f);assertFalse(DanmakuLayout056.visible(8.1f,8f))}
 @Test fun danmakuTravelAndAreaAreIndependent(){assertEquals(960f,DanmakuLayout056.travel(1920f,140f,50));assertEquals(960f,DanmakuLayout056.xAt(1920f,140f,50,8f,8f));assertEquals(270f,DanmakuLayout056.area(1080f,25))}
 @Test fun detailFactsNormalizeForBrowse(){assertEquals("日本",DetailFact056.display("Japan"));assertEquals("中国大陆",DetailFact056.display("China"));assertEquals("日本",DetailFact056.normalize("Japan"));assertEquals("喜剧",DetailFact056.normalize("Comedy"));assertEquals("2022",DetailFact056.normalize("2022"));assertEquals("",DetailFact056.normalize("电视剧 / 第1季"))}
 @Test fun watchMarkersUseDistinctGreenPurplePinkGradients(){assertEquals(listOf(0xff25a86b.toInt(),0xff78e6a8.toInt()),WatchVisuals056.argb(WatchState.COMPLETED));assertEquals(0xff7650da.toInt(),WatchVisuals056.argb(WatchState.WATCHING).first());assertEquals(0xffe34d9b.toInt(),WatchVisuals056.argb(WatchState.PLANNED).first())}
 @Test fun quarterCrossesYear(){val r=AnimeSeason056.range(2026,3);assertEquals("2026-10-01",r.first.toString());assertEquals("2027-01-01",r.second.toString())}
 @Test fun xpathRelativeToEachResult(){val r=JSONObject("""{"baseURL":"https://example.org","searchList":"//div[@class='item']","searchResult":"//a","searchName":"//a","chapterRoads":"//ul","chapterResult":"//li/a"}""");val found=AnimeRules056.parseSearch(r,"<div class=item><a href='/one'>甲</a></div><div class=item><a href='/two'>乙</a></div>");assertEquals(listOf("甲","乙"),found.map{it.title});val roads=AnimeRules056.parseDetail(r,"/one","<ul><li><a href='/play/1'>第1集</a></li></ul><ul><li><a href='/play/2'>第2集</a></li></ul>");assertEquals(2,roads.size);assertEquals("https://example.org/play/2",roads[1].episodes[0].url)}
 @Test fun xpathLiteSupportsBundledRuleShapes(){val doc=org.jsoup.Jsoup.parse("""<main><div><div><ul class='anthology-list-play size'><li><a href='/play/1'>第1集</a></li></ul></div></div><section class='panel'><div id='playlist-one' class='lists-box'><a href='/index.php/vod/play/2'>第2集</a></div></section><div class='video-card'><span class='video-card-title'>测试番</span></div><div class='routes'><div class='line_button1'></div><a class='circuit_switch1' href='/switched'>切换</a></div></main>""");val road=doc.selectFirst("ul.anthology-list-play")!!;assertEquals("第1集",XPathLite056.select(road,".//a[contains(@href,'/play/')]").single().text());assertEquals(1,XPathLite056.select(doc,"//div[starts-with(@id,'playlist')][contains(@class,'lists-box')]").size);assertEquals("测试番",XPathLite056.text(doc.selectFirst("div.video-card")!!,"//span[contains(@class,'video-card-title')]"));val switch=XPathLite056.select(doc.selectFirst("div.line_button1")!!,"""/self::*[@class='line_button1']/following-sibling::a[@class='circuit_switch1'] | /self::*[@class='line_button2']/following-sibling::a[@class='circuit_switch2']""");assertEquals("切换",switch.single().text())}
 @Test fun rootArrayApi(){val r=JSONObject("""{"searchMode":"api","searchApiConfig":{"listPath":"$[*]","namePath":"$.title","sourcePath":"$.id"}}""");assertEquals("42",AnimeRules056.parseSearch(r,"""[{"id":42,"title":"测试"}]""").single().id)}
 @Test fun delimitedPreservesEveryRoad(){val r=JSONObject("""{"baseURL":"https://example.org","chapterMode":"api","chapterApiConfig":{"format":"delimited","roadNamesPath":"$.from","roadEpisodesPath":"$.urls","roadSeparator":"@@","episodeSeparator":"#","fieldSeparator":"|"}}""");val roads=AnimeRules056.parseDetail(r,"7","""{"from":"中文@@原声","urls":"第1集|/1#第2集|/2@@第1集|/3"}""");assertEquals(2,roads.size);assertEquals(2,roads[0].episodes.size);assertEquals("原声",roads[1].name)}
 @Test fun directEpisodeBypassesProxyPage(){val r=JSONObject("""{"baseURL":"https://example.org","chapterMode":"api","chapterApiConfig":{"format":"delimited","roadNamesPath":"$.from","roadEpisodesPath":"$.urls","roadSeparator":"@@","episodeSeparator":"#","fieldSeparator":"|","episodePage":{"url":"https://proxy.example.org/play","query":{"url":"@episodeUrl"}}}}""");val roads=AnimeRules056.parseDetail(r,"7","""{"from":"线路","urls":"第1集|https://cdn.example.org/01.mp4"}""");assertEquals("https://cdn.example.org/01.mp4",roads.single().episodes.single().url)}
 @Test fun nestedApi(){val r=JSONObject("""{"baseURL":"https://example.org","chapterMode":"api","chapterApiConfig":{"roadsPath":"$.sources[*]","roadNamePath":"$.name","episodesPath":"$.episodes[*]","episodeNamePath":"$.title","episodeUrlPath":"$.id","episodePage":{"url":"https://example.org/@source/@episodeUrl"}}}""");assertEquals("https://example.org/42/8",AnimeRules056.parseDetail(r,"42","""{"sources":[{"name":"原声","episodes":[{"title":"第8集","id":8}]}]}""").single().episodes.single().url)}
 @Test fun chineseAliasNeedsExactYearAndOriginal(){val e=AnimeEntry056(Work("1","原题",year="2026",provider="anilist",aliases=listOf("原题")));val good="""{"data":[{"name":"原题","name_cn":"中文名","date":"2026-04-01"}]}""";assertEquals("中文名",AnimeSeason056.supplement(listOf(e),good).single().work.title);assertEquals("原题",AnimeSeason056.supplement(listOf(e),good.replace("2026","2025")).single().work.title)}
}
